M="pharm-neuro"
BOSS=dict(th="เคสใหญ่: มือสั่นเดินช้า",en="Boss case: The shaking hand",
case="A 67-year-old man has a 1-year history of resting tremor of the right hand, slowness of movement and a shuffling gait. Examination shows cogwheel rigidity and reduced arm swing. He is cognitively intact.",
qs=[
("Most effective symptomatic drug:",["Levodopa with carbidopa","Benztropine (antimuscarinic)","Haloperidol (D₂ antagonist)","Donepezil (AChE inhibitor)"],0,"Dopamine precursor."),
("Carbidopa is added because it:",["Inhibits peripheral DOPA decarboxylase","Is converted to dopamine in the brain","Directly stimulates D₂ receptors","Inhibits catechol-O-methyltransferase centrally"],0,"↑ CNS levodopa and ↓ peripheral side effects."),
("A dopamine agonist such as pramipexole may cause:",["Impulse-control disorders and somnolence","Agranulocytosis and myocarditis","Hepatotoxicity and pancreatitis","Tardive dyskinesia and hyperprolactinemia"],0,"Gambling, hypersexuality."),
("Selegiline and rasagiline act by:",["Selective MAO-B inhibition","Peripheral COMT inhibition","NMDA receptor antagonism","Direct D₂ receptor agonism"],0,"↑ Dopamine availability."),
("Which drug worsens his symptoms and should be avoided?",["Metoclopramide","Amantadine","Entacapone","Trihexyphenidyl"],0,"D₂ antagonists cause/aggravate parkinsonism."),
("Benztropine is mainly useful for:",["Tremor and rigidity","Bradykinesia and freezing","Dementia and cognitive decline","Orthostatic hypotension"],0,"Antimuscarinic. Avoid in elderly due to confusion."),
],pass_=4)
T={
"neuromap":[("Benzodiazepines enhance GABA-A by:",["↑ Frequency of Cl⁻ channel opening","↑ Duration of opening","Direct channel opening at all doses","Blocking glutamate"],0,"Barbiturates ↑ duration."),
 ("Ethosuximide blocks:",["Thalamic T-type Ca²⁺ channels","Voltage-gated Na⁺ channels","Neuronal GABA transaminase","Synaptic vesicle protein SV2A"],0,"First-line for absence seizures."),
 ('A 40-year-old woman with refractory status epilepticus is placed in a pentobarbital coma in the ICU. At the GABA-A receptor, this drug acts by:', ['↑ Duration of Cl⁻ channel opening', '↑ Frequency of Cl⁻ channel opening', 'Blocking T-type Ca²⁺ channels', 'Inhibiting GABA transaminase'], 0, 'Barbiturates prolong channel opening (and directly open it at high doses); benzodiazepines increase opening frequency.', 2)],
"aed-focal":[("Phenytoin adverse effects include:",["Gingival hyperplasia, hirsutism, nystagmus","Weight loss, kidney stones, paresthesias","Pancreatitis, alopecia, weight gain","Permanent visual field constriction"],0,"Also teratogenic (fetal hydantoin), SJS, CYP induction."),
 ("Carbamazepine is first-line for:",["Trigeminal neuralgia and focal seizures","Absence and myoclonic seizures","Infantile spasms (West syndrome)","Status epilepticus and eclampsia"],0,"Agranulocytosis, SIADH, SJS (HLA-B*15:02)."),
 ('A 30-year-old woman of Han Chinese descent with focal impaired-awareness seizures starts a new antiseizure drug. Three weeks later she has fever, painful target lesions and oral and conjunctival erosions with < 10% epidermal detachment. Genotyping shows HLA-B*15:02. Which drug was most likely started?', ['Carbamazepine', 'Levetiracetam', 'Ethosuximide', 'Gabapentin'], 0, 'HLA-B*15:02 strongly predicts carbamazepine-induced Stevens–Johnson syndrome, so screening is advised in Asian patients before starting it.', 2)],
"aed-absence":[("Ethosuximide side effects:",["GI upset, fatigue, headache","Gingival hyperplasia, hirsutism","Weight gain, alopecia, tremor","Kidney stones, paresthesias"],0,"Stevens–Johnson rare."),
 ("Which drug can worsen absence seizures?",["Carbamazepine","Ethosuximide","Valproate","Lamotrigine"],0,"Also phenytoin."),
 ('A 7-year-old girl has brief staring spells many times a day, each lasting about 10 seconds without postictal confusion; one is provoked by hyperventilation. EEG shows 3-Hz spike-and-wave discharges. The drug of choice acts by:', ['Blocking thalamic T-type Ca²⁺ channels', 'Prolonging Na⁺ channel inactivation', 'Binding synaptic vesicle protein SV2A', 'Increasing GABA-A channel open time'], 0, 'Childhood absence epilepsy is treated with ethosuximide, which blocks thalamic T-type Ca²⁺ channels; Na⁺ channel blockers like carbamazepine can worsen absences.', 3)],
"aed-broad":[("Valproate is contraindicated in pregnancy because of:",["Neural tube defects","Cleft lip only","Gray baby syndrome","Kernicterus"],0,"Also hepatotoxicity and pancreatitis."),
 ("Lamotrigine must be titrated slowly to avoid:",["Stevens–Johnson syndrome","Kidney stones","Hyponatremia","Gingival hyperplasia"],0,"Valproate raises lamotrigine levels."),
 ('A 25-year-old woman with juvenile myoclonic epilepsy (morning jerks, generalized tonic-clonic seizures) is well controlled on valproate but plans pregnancy next year. Which drug is the most appropriate replacement?', ['Levetiracetam', 'Carbamazepine', 'Phenytoin', 'Ethosuximide'], 0, 'Valproate is highly teratogenic (neural tube defects); levetiracetam is broad-spectrum and safer in pregnancy. Carbamazepine and phenytoin can worsen myoclonic seizures.', 3)],
"barb-bzd":[("Benzodiazepines are used for:",["Anxiety and alcohol withdrawal","Absence seizures as first-line","Parkinson disease motor symptoms","Long-term migraine prophylaxis"],0,"Also status epilepticus. Risk of dependence and additive CNS depression with alcohol."),
 ("Barbiturates are contraindicated in:",["Porphyria","Epilepsy","Anxiety","Insomnia"],0,"Induce ALA synthase."),
 ('A 48-year-old man with heavy daily alcohol use is admitted for hip surgery. Forty-eight hours later he has tremor, sweating, HR 118/min, BP 165/100 mm Hg and visual hallucinations. Most appropriate drug and its action?', ['Chlordiazepoxide; ↑ GABA-A opening frequency', 'Haloperidol; dopamine D₂ receptor antagonism', 'Phenytoin; prolongs Na⁺ channel inactivation', 'Naltrexone; μ-opioid receptor antagonism'], 0, "Alcohol withdrawal is treated with a benzodiazepine, which substitutes for alcohol's GABA-A effect; haloperidol lowers the seizure threshold and does not treat withdrawal.", 3)],
"insomnia":[("Zolpidem acts at:",["BZ₁ subtype of GABA-A receptor","MT₁/MT₂ melatonin receptors","OX₁/OX₂ orexin receptors","Central histamine H₁ receptors"],0,"Nonbenzodiazepine hypnotic; complex sleep behaviors."),
 ("Suvorexant works by:",["Orexin receptor antagonism","Melatonin receptor agonism","GABA-A positive modulation","Histamine H₁ blockade"],0,"Avoid in narcolepsy."),
 ('A 68-year-old woman takes a nightly hypnotic for sleep-onset insomnia. Her husband finds her cooking in the kitchen at 3 AM, and she has no memory of it the next morning. Which drug most likely caused this?', ['Zolpidem', 'Ramelteon', 'Suvorexant', 'Doxepin'], 0, "Complex sleep behaviors (sleepwalking, sleep-driving) are a boxed warning for the BZ₁-selective 'Z-drugs'; ramelteon (melatonin agonist) does not cause them.", 2)],
"triptans":[("Sumatriptan acts as a:",["5-HT₁B/1D agonist","5-HT₃ antagonist","5-HT₂A antagonist","Dopamine agonist"],0,"Vasoconstriction and inhibition of trigeminal activation."),
 ("Triptans are contraindicated in:",["Coronary artery disease","Mild persistent asthma","Type 2 diabetes mellitus","Gout and hyperuricemia"],0,"Coronary vasospasm; also Prinzmetal angina."),
 ('A 45-year-old woman has recurrent unilateral throbbing headaches with nausea and photophobia lasting 12 hours. She also has variant (Prinzmetal) angina with documented coronary vasospasm. Which abortive drug is contraindicated?', ['Sumatriptan', 'Naproxen', 'Metoclopramide', 'Acetaminophen'], 0, 'Triptans are 5-HT₁B/1D agonists that constrict coronary arteries, so they are avoided in vasospastic angina and CAD; NSAIDs and antiemetics are safe options.', 2)],
"pd":[("Entacapone inhibits:",["Peripheral COMT","MAO-B","DOPA decarboxylase","Dopamine receptors"],0,"Prolongs levodopa effect."),
 ("Long-term levodopa can cause:",["Dyskinesias and on–off fluctuations","Agranulocytosis and myocarditis","Hyperprolactinemia and galactorrhea","Gingival hyperplasia and hirsutism"],0,"Wearing-off with disease progression."),
 ("A 68-year-old man with Parkinson disease has taken levodopa–carbidopa for 6 years. His tremor and rigidity now return about 3 hours after each dose, before the next one is due. Which added drug most directly prolongs each dose's effect?", ['Entacapone', 'Benztropine', 'Haloperidol', 'Donepezil'], 0, 'Wearing-off is managed with a COMT inhibitor (entacapone), which blocks peripheral levodopa breakdown; benztropine helps tremor but does not extend levodopa action.', 3)],
"neurodeg":[("Donepezil acts by:",["Acetylcholinesterase inhibition","NMDA receptor antagonism","Dopamine receptor agonism","Selective MAO-B inhibition"],0,"Used in Alzheimer disease."),
 ("Riluzole treats ALS by:",["↓ Glutamate excitotoxicity","↑ Acetylcholine via AChE block","Depleting presynaptic dopamine","Suppressing autoimmune T cells"],0,"Modest survival benefit."),
 ('A 74-year-old woman has 3 years of progressive memory loss and now gets lost in her neighborhood. MMSE is 20/30 and MRI shows hippocampal atrophy. After starting a drug she develops bradycardia and diarrhea. The drug acts by:', ['Acetylcholinesterase inhibition', 'NMDA receptor antagonism', 'Muscarinic receptor blockade', 'Selective MAO-B inhibition'], 0, 'Alzheimer disease is treated with donepezil; ↑ ACh causes cholinergic effects (bradycardia, diarrhea). Memantine (NMDA antagonist) does not cause these.', 3)],
"localanes":[("Local anesthetics block:",["Voltage-gated Na⁺ channels","Voltage-gated K⁺ channels","GABA-A chloride channels","Nicotinic ACh receptors"],0,"They bind from inside the axon. Small myelinated fibers are blocked first."),
 ("Why add epinephrine to lidocaine?",["Prolongs block via vasoconstriction","Increases spread through tissues","Prevents lidocaine-induced bradycardia","Speeds onset by raising tissue pH"],0,"Vasoconstriction ↓ systemic absorption. Avoid in digits and penis classically."),
 ('A 32-year-old man has a fluctuant, erythematous thigh abscess. After lidocaine is infiltrated into the inflamed tissue, incision is still very painful. Why is the local anesthetic less effective here?', ['Acidic pH keeps drug in charged form', 'Pus enzymatically degrades the amide', 'Inflammation strips the nerve myelin', 'Infection blocks the GABA-A receptors'], 0, 'Local anesthetics are weak bases that must be uncharged to cross the nerve membrane; acidic infected tissue keeps them ionized. Amides are metabolized in the liver, not by pus.', 3)],
"genanes":[("Inhaled anesthetic potency is inversely related to:",["MAC","Blood/gas partition coefficient","Lipid solubility","Molecular weight"],0,"Low MAC = high potency."),
 ("Malignant hyperthermia is treated with:",["Dantrolene","Succinylcholine","Neostigmine","Propofol"],0,"Ryanodine receptor defect triggered by volatile anesthetics and succinylcholine."),
 ('A 19-year-old man undergoing appendectomy under sevoflurane and succinylcholine develops masseter rigidity, rising end-tidal CO₂, tachycardia and a temperature of 40.5 °C. The drug of choice acts by:', ['Blocking RyR1 Ca²⁺ release from the SR', 'Blocking nicotinic receptors at the NMJ', 'Inhibiting hypothalamic heat production', 'Activating SERCA Ca²⁺ reuptake pumps'], 0, 'Malignant hyperthermia (RyR1 defect) is treated with dantrolene, which blocks Ca²⁺ release from the sarcoplasmic reticulum; nondepolarizing blockers do not stop the intracellular Ca²⁺ leak.', 3)],
"nmb":[("Succinylcholine can cause:",["Hyperkalemia","Hypokalemia","Hypertension only","Seizures"],0,"Depolarizing; dangerous in burns, crush injury, denervation."),
 ("Sugammadex reverses:",["Rocuronium and vecuronium","Succinylcholine and mivacurium","Fentanyl and morphine","Midazolam and diazepam"],0,"Encapsulates the steroidal blocker."),
 ('A 35-year-old man with 40% total body surface area burns sustained 10 days ago needs rapid-sequence intubation for débridement. Succinylcholine is avoided because it may cause cardiac arrest through:', ['Hyperkalemia from extrajunctional AChRs', 'Malignant hyperthermia from RyR1 defect', 'Prolonged apnea from low cholinesterase', 'Histamine release causing hypotension'], 0, 'Burns, crush injury and denervation upregulate extrajunctional ACh receptors, so depolarization releases large amounts of K⁺; MH requires an inherited RyR1 mutation.', 2)],
"relax":[("Baclofen acts at:",["GABA-B receptors in the spinal cord","GABA-A receptors in the cortex","α₂ receptors in the spinal cord","Ryanodine receptors in muscle"],0,"Used for spasticity."),
 ("Cyclobenzaprine is structurally similar to:",["Tricyclic antidepressants","Benzodiazepine anxiolytics","Phenylpiperidine opioids","Barbiturate sedatives"],0,"Anticholinergic and sedating."),
 ('A 30-year-old woman with multiple sclerosis has painful spasticity and flexor spasms of both legs that interfere with walking. Which drug is most appropriate?', ['Baclofen', 'Cyclobenzaprine', 'Succinylcholine', 'Neostigmine'], 0, 'Baclofen (GABA-B agonist in the spinal cord) treats spasticity from MS and spinal cord injury; cyclobenzaprine is for acute musculoskeletal spasm, not upper motor neuron spasticity.', 2)],
"opioids":[("Which opioid effect does NOT develop tolerance?",["Miosis and constipation","Analgesia","Respiratory depression","Euphoria"],0,"Hence chronic constipation needs laxatives."),
 ("Opioids act on:",["μ, δ, κ receptors (Gi-coupled)","GABA-A receptors (Cl⁻ channels)","NMDA receptors (cation channels)","Nicotinic receptors (ion channels)"],0,"↓ Ca²⁺ influx presynaptically, ↑ K⁺ efflux postsynaptically."),
 ('A 58-year-old man with metastatic lung cancer has taken escalating oral morphine for 6 months. His pain is controlled and early sedation resolved, but he has hard stools every 5 days despite osmotic and stimulant laxatives. Best drug and its action?', ['Methylnaltrexone; peripheral μ antagonist', 'Buprenorphine; central partial μ agonist', 'Loperamide; peripheral μ-receptor agonist', 'Metoclopramide; central D₂ antagonist'], 0, 'Constipation shows no tolerance; a peripherally restricted μ antagonist relieves it without reversing analgesia. Loperamide is a μ agonist and would worsen it.', 3)],
"mixed":[("Tramadol lowers seizure threshold and can cause:",["Serotonin syndrome","Malignant hyperthermia","Agranulocytosis","Lupus"],0,"Weak μ agonist plus SNRI action."),
 ("Buprenorphine is a:",["Partial μ agonist","Full μ agonist","Pure antagonist","κ antagonist"],0,"Can precipitate withdrawal in opioid-dependent patients."),
 ('A 45-year-old man taking sertraline for depression is prescribed a new analgesic for back pain. Two days later he is agitated and diaphoretic with temperature 38.9 °C, inducible ankle clonus and hyperreflexia. Which property of the analgesic explains this?', ['Inhibits serotonin and NE reuptake', 'Full agonist at κ-opioid receptors', 'Antagonist at dopamine D₂ receptors', 'Blocks muscarinic ACh receptors'], 0, 'Tramadol is a weak μ agonist that also inhibits 5-HT and NE reuptake, so with an SSRI it can cause serotonin syndrome; D₂ antagonism relates to neuroleptic malignant syndrome instead.', 3)],
"glaucoma":[("Latanoprost lowers IOP by:",["↑ Uveoscleral aqueous outflow","↓ Aqueous humor production","Miosis → ↑ trabecular outflow","Osmotic vitreous dehydration"],0,"PGF₂α analog. Darkens iris color."),
 ("Timolol lowers IOP by:",["↓ Aqueous humor production","↑ Uveoscleral aqueous outflow","Miosis → ↑ trabecular outflow","Osmotic vitreous dehydration"],0,"β-blocker acting on the ciliary epithelium. Systemic absorption may worsen asthma."),
 ('A 64-year-old man with moderate persistent asthma is found to have open-angle glaucoma (IOP 28 mm Hg, cupped optic discs). Which eye drop should be avoided?', ['Timolol', 'Latanoprost', 'Brimonidine', 'Dorzolamide'], 0, 'Topical nonselective β-blockers are absorbed systemically and can trigger bronchospasm; prostaglandin analogs, α₂ agonists and carbonic anhydrase inhibitors are alternatives.', 2)],
"status":[("First-line drug for status epilepticus:",["IV lorazepam (or IM midazolam)","IV phenytoin as monotherapy","Oral valproate loading dose","Oral carbamazepine loading"],0,"Then fosphenytoin, valproate or levetiracetam."),
 ("Fosphenytoin is preferred over phenytoin IV because:",["Less infusion-site injury and hypotension","It needs no cardiac monitoring","It has no CYP450 drug interactions","It does not cause gingival hyperplasia"],0,"Prodrug; purple glove syndrome with phenytoin."),
 ('A 28-year-old man with epilepsy has a generalized tonic-clonic seizure lasting 10 minutes. He received two doses of IV lorazepam and is still seizing; airway and IV access are secured. Most appropriate next drug?', ['IV fosphenytoin', 'Oral carbamazepine', 'Oral ethosuximide', 'IM haloperidol'], 0, 'After benzodiazepines fail, a second-line IV agent (fosphenytoin, valproate or levetiracetam) is loaded; oral drugs act too slowly and haloperidol lowers the seizure threshold.', 2)],
}
